import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { PublicationReceiptsEntity } from "#/modules/source/schema/entities/publication-receipts.entity.ts";
import * as PublicationReceipts from "#/modules/source/schema/types/publication-receipts/index.ts";

/**
 * Repository of Publication Receipts: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class PublicationReceiptsRepository
  extends EntityRepository<
    PublicationReceiptsEntity,
    PublicationReceipts.Types.PublicationReceiptsSortableField,
    PublicationReceipts.Types.PublicationReceiptsEditableField,
    PublicationReceipts.Types.PublicationReceiptsSelectableField,
    PublicationReceipts.Types.IPublicationReceiptsCreatable
  >
  implements
    IUpdatableRepository<
      PublicationReceiptsEntity,
      PublicationReceipts.Types.IPublicationReceiptsUpdatable
    >
{
  constructor(
    @InjectRepository(PublicationReceiptsEntity)
    repository: Repository<PublicationReceiptsEntity>,
  ) {
    super(repository, PublicationReceipts.Config.PUBLICATION_RECEIPTS_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: PublicationReceipts.Types.IPublicationReceiptsUpdatable,
  ): Promise<PublicationReceiptsEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the publication receipts with this idempotency key (unique). */
  async findByIdempotencyKey(
    idempotencyKey: NonNullable<PublicationReceiptsEntity["idempotencyKey"]>,
  ): Promise<PublicationReceiptsEntity | null> {
    return await this.findOne({ idempotencyKey, deletedAt: IsNull() });
  }

  /** Find the publication receipts with this publication ref id (unique). */
  async findByPublicationRef(
    publicationRefId: NonNullable<PublicationReceiptsEntity["publicationRefId"]>,
  ): Promise<PublicationReceiptsEntity | null> {
    return await this.findOne({ publicationRefId, deletedAt: IsNull() });
  }
}
